function __buildCycleList(values, pos) {
  if (values.length === 0) return null;
  const nodes = values.map((val) => ({ val, next: null }));
  for (let i = 0; i < nodes.length - 1; i += 1) nodes[i].next = nodes[i + 1];
  if (pos >= 0 && pos < nodes.length) nodes[nodes.length - 1].next = nodes[pos];
  return nodes[0];
}
function __runHasCycle(values, pos) {
  return hasCycle(__buildCycleList(values, pos));
}

