    const dummy = { val: 0, next: null };
    let cur = dummy;
    for (const v of arr) {
      cur.next = { val: v, next: null };
      cur = cur.next;
    }
    return dummy.next;
  };
  const toArray = (head) => {
    const out = [];
    while (head) {
      out.push(head.val);
      head = head.next;
    }
    return out;
  };
  const lists = arrays.map(toList).filter(Boolean);
  if (lists.length === 0) return [];
  while (lists.length > 1) {
    const a = lists.shift();
    const b = lists.shift();
    lists.push(mergeTwo(a, b));
  }
  return toArray(lists[0]);
  function mergeTwo(l1, l2) {
